begin;
select plan(25);
select has_table('public','together_character_activity_templates','Characters have authored activity templates');
select has_table('public','together_character_schedule_events','Routine reality persists per companion instance');
select has_table('public','together_character_schedule_overrides','Schedule changes retain audit history');
select has_column('public','together_character_instances','current_schedule_event_id','Character caches its current schedule event');
select has_column('public','together_character_instances','current_interruptibility','Character availability is explicit');
select has_column('public','together_character_instances','current_presence_source','Cached presence records how reality was resolved');
select has_column('public','together_character_instances','life_engine_version','Life Engine rollout is inspectable');
select has_column('public','together_character_schedule_events','continuity_id','Schedule reality is continuity-scoped');
select has_column('public','together_character_schedule_events','priority','Schedule conflicts use canonical priority');
select has_column('public','together_character_schedule_events','visibility','Schedule disclosure is intentional');
select has_column('public','together_character_schedule_events','interruptibility','Presence communicates availability');
select has_column('public','together_character_schedule_events','generation_key','Generation is idempotent');
select has_column('public','together_character_schedule_events','participant_instance_ids','Future multi-person scenes are supported');
select ok((select relrowsecurity from pg_class where oid='public.together_character_schedule_events'::regclass),'Schedule events use RLS');
select ok((select relrowsecurity from pg_class where oid='public.together_character_schedule_overrides'::regclass),'Schedule overrides use RLS');
select ok(exists(select 1 from pg_indexes where schemaname='public' and indexname='together_schedule_events_presence_idx'),'Presence lookup has a time-window index');
select ok(exists(select 1 from pg_indexes where schemaname='public' and indexname='together_schedule_events_location_idx'),'Location presence has a time-window index');
select ok(exists(select 1 from pg_constraint where conrelid='public.together_character_schedule_events'::regclass and contype='u' and pg_get_constraintdef(oid) like '%character_instance_id%' and pg_get_constraintdef(oid) like '%generation_key%'),'Concurrent generation deduplicates by instance and generation key');
select trigger_is('public','together_character_schedule_events','together_schedule_event_owner','public','kivelle_validate_schedule_event_owner','Schedule rows validate continuity ownership');
select trigger_is('public','together_shared_plans','together_shared_plan_schedule_override','public','kivelle_apply_plan_schedule_override','Shared plans override generated life without deleting it');
select ok((select count(*) from public.together_character_templates t join public.together_character_versions v on v.character_template_id=t.id where t.slug in ('maya','chloe','alex','sofia','avery','riley','elena','harper') and v.life_config ? 'sleep' and v.life_config ? 'occupation' and v.life_config ? 'scheduling')>=8,'Every primary companion has an authored LifeProfile');
select ok(exists(select 1 from public.together_character_activity_templates a join public.together_character_versions v on v.id=a.character_version_id join public.together_character_templates t on t.id=v.character_template_id where t.slug='maya' and a.activity_key='photo_walk'),'Maya keeps photography as a high-affinity life activity');
select ok(exists(select 1 from public.together_character_activity_templates where activity_key='home_evening'),'Every version receives conservative home-life fallback activity');
select ok(exists(select 1 from pg_constraint where conrelid='public.together_character_schedule_events'::regclass and pg_get_constraintdef(oid) like '%user_commitment%' and pg_get_constraintdef(oid) like '%spontaneous_activity%'),'Priority enum spans plans through spontaneous fillers');
select ok(exists(select 1 from pg_constraint where conrelid='public.together_character_schedule_overrides'::regclass and pg_get_constraintdef(oid) like '%conversation_extension%'),'Conversation extensions are canonical override reasons');
select * from finish();
rollback;

